"""Tests for clock implementations."""

import unittest

from slidewin.clock import ManualClock


class ManualClockTests(unittest.TestCase):
    def test_cannot_advance_backwards(self):
        clk = ManualClock(start=5)

        with self.assertRaisesRegex(
            ValueError, "^cannot advance clock backwards$"
        ):
            clk.advance(-1)

        self.assertEqual(clk.now(), 5.0)


if __name__ == "__main__":
    unittest.main()

"""Tests for limiter configuration."""

import unittest

from slidewin import __version__
from slidewin.config import LimiterConfig


class LimiterConfigTests(unittest.TestCase):
    def test_defaults(self):
        config = LimiterConfig()
        self.assertEqual(config.window_seconds, 60)
        self.assertEqual(config.default_limit, 5)

    def test_package_version(self):
        self.assertEqual(__version__, "0.2.1")


if __name__ == "__main__":
    unittest.main()
